/**
 * The links between the sibling pages of one section, with the current page marked (`design/components/section-nav.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/section-nav.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  agentPress,
  derived,
  elementRef,
  mountEffect,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/section-nav.module.css'

export interface SectionNavItem {
  label: string
  href: string
}

/** The links between the sibling pages of one section, with the current page marked: the inputs it takes, by the React member's prop names. */
export interface SectionNavProps {
  /**
   * The `href` of the item whose page the reader is on; without it no item is current. It is
   * compared as the page it names, so a trailing slash, a query or a hash on either side does
   * not stop the match, and neither does an origin on `current` (`location.href`).
   */
  current?: string
  /**
   * One link per sibling page, in the order drawn.
   */
  items: SectionNavItem[]
  /**
   * The landmark's accessible name, which tells this navigation from the page's others.
   */
  label: string
}

/** The links between the sibling pages of one section, with the current page marked. */
@Component({
  selector: 'pm-section-nav',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref],
  // prettier-ignore
  template: `<nav
[attr.class]="e1()"
[attr.aria-label]="e2()"
data-member="section-nav"
[pmRef]="root"
><!-- list -->
<ul
[attr.class]="e3()"
>@for (item of e4(); track e5(item, $index); let index = $index) {<!-- item -->
<li
[attr.class]="e6()"
><a
[attr.class]="e7()"
[attr.href]="e8(item)"
[attr.aria-current]="e9(index)"
(click)="h1($event, item)"
><!-- label -->
<span
[attr.class]="e10()"
>{{ e11(item) }}</span></a></li>}</ul></nav>`,
})
export class SectionNav {
  /**
   * The `href` of the item whose page the reader is on; without it no item is current. It is
   * compared as the page it names, so a trailing slash, a query or a hash on either side does
   * not stop the match, and neither does an origin on `current` (`location.href`).
   */
  readonly current = input<SectionNavProps['current']>(undefined)
  /**
   * One link per sibling page, in the order drawn.
   */
  readonly items = input.required<SectionNavProps['items']>()
  /**
   * The landmark's accessible name, which tells this navigation from the page's others.
   */
  readonly label = input.required<SectionNavProps['label']>()
  /**
   * The app's router, for every item (`link.md` §Routing): a click that would navigate this tab
   * calls it in place of the browser.
   */
  readonly onNavigate = output<string>({ alias: 'navigate' })
  protected readonly $ = useMember({
    events: ['navigate'],
    props: { current: () => this.current(), items: () => this.items(), label: () => this.label() },
  })
  protected readonly $p = this.$.props
  protected readonly root = elementRef<HTMLElement>()
  protected readonly originOf = derived(
    () =>
      (href: string): string | undefined =>
        /^(?:[a-z][a-z\d+.-]*:)?\/\/[^/?#]*/iu.exec(href)?.[0].toLowerCase(),
  )
  protected readonly pageOf = derived(() => (href: string): string => {
    if (href.startsWith('#') || href.startsWith('?')) return href
    const origin = this.originOf.value(href) ?? ''
    const path = href.slice(origin.length).replace(/[?#].*$/u, '')
    if (path === '') return origin === '' ? '' : '/'
    return path.length > 1 ? path.replace(/\/+$/u, '') : path
  })
  protected readonly currentAt = derived(() =>
    ((at: string | undefined): number => {
      if (at === undefined) return -1
      const exact = this.$p.items.findIndex((item) => item.href === at)
      if (exact !== -1) return exact
      const page = this.pageOf.value(at)
      const origin = this.originOf.value(at)
      return this.$p.items.findIndex((item) => {
        const itemOrigin = this.originOf.value(item.href)
        return (
          this.pageOf.value(item.href) === page &&
          (itemOrigin === undefined || itemOrigin === origin)
        )
      })
    })(this.$p.current),
  )
  protected readonly navigatesHere = derived(
    () =>
      (event: MouseEvent): boolean =>
        !event.defaultPrevented &&
        event.button === 0 &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey &&
        !event.altKey,
  )
  protected readonly route = derived(() => (event: MouseEvent, href: string): void => {
    if (!this.$.listening(this.onNavigate, 'onNavigate') || !this.navigatesHere.value(event)) return
    event.preventDefault()
    this.$.emit(this.onNavigate, 'onNavigate', href)
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.nav
  }

  protected e2() {
    return this.$p.label
  }

  protected e3() {
    return styles.list
  }

  e4() {
    return this.$p.items
  }

  protected e5(item: Each<ReturnType<SectionNav['e4']>>, index: number) {
    return `${index}:${item.href}`
  }

  protected e6() {
    return styles.item
  }

  protected e7() {
    return styles.link
  }

  protected e8(item: Each<ReturnType<SectionNav['e4']>>) {
    return item.href
  }

  protected e9(index: number) {
    return index === this.currentAt.value ? 'page' : undefined
  }

  protected h1($event: MouseEvent, item: Each<ReturnType<SectionNav['e4']>>): void {
    this.route.value($event, item.href)
  }

  protected e10() {
    return styles.label
  }

  protected e11(item: Each<ReturnType<SectionNav['e4']>>) {
    return item.label
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'SectionNav',
      element: () => this.root.value,
      state: () => ({
        current: this.$p.items[this.currentAt.value]?.href ?? null,
        items: this.$p.items
          .filter((item, at) => this.$p.items.findIndex((other) => other.href === item.href) === at)
          .map((item) => ({ id: item.href, label: item.label })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            agentPress(
              this.root.value?.querySelectorAll('a')[
                this.$p.items.findIndex((item) => item.href === value)
              ],
            ),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
